    while (i < bb.limit()) {
        int b = bb.get(i) & 0xFF;
        if (b < 0x80) {
            sb.append((char) b);
            i++;
        } else if (b < 0xC0) {
            // invalid octet
            return i;
        } else if (b < 0xE0) {
            if (i + 1 >= bb.limit()) {
                // incomplete sequence
                return i;
            }
            int b1 = bb.get(i + 1) & 0xFF;
            if ((b1 & 0xC0) != 0x80) {
                // invalid sequence
                return i;
            }
            sb.append((char) (((b & 0x1F) << 6) | (b1 & 0x3F)));
            i += 2;
        } else if (b < 0xF0) {
            if (i + 2 >= bb.limit()) {
                // incomplete sequence
                return i;
            }
            int b1 = bb.get(i + 1) & 0xFF;
            int b2 = bb.get(i + 2) & 0xFF;
            if (((b1 & 0xC0) != 0x80) || ((b2 & 0xC0) != 0x80)) {
                // invalid sequence
