    // Write the length of the string
    lb.writeInt(str.length());

    // Write the characters of the string
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if (c < 0x80) {
            lb.writeByte((byte) c);
        } else if (c < 0x800) {
            lb.writeByte((byte) (0xc0 | (c >> 6)));
            lb.writeByte((byte) (0x80 | (c & 0x3f)));
