    int pos = 0;
    while (pos < str.length()) {
        char ch = str.charAt(pos);
        if (ch == '\\') {
            pos++;
            ch = str.charAt(pos);
            switch (ch) {
                case 'b':
                    sb.append('\b');
                    break;
                case 't':
                    sb.append('\t');
                    break;
                case 'n':
                    sb.append('\n');
                    break;
                case 'f':
                    sb.append('\f');
