                case '\\':
                    sb.append('\\');
                    break;
                case '\'':
                    sb.append('\'');
                    break;
                case '\"':
                    sb.append('\"');
                    break;
                case 'u':
                    pos++;
                    int code = Integer.parseInt(str.substring(pos, pos + 4), 16);
                    sb.append((char) code);
                    pos += 4;
                    break;
                default:
                    throw new Exception("Illegal escape character: " + ch);
            }
        } else {
            sb.append(ch);
        }
        pos++;
    }
    return sb.toString();
}

