    for (E edge : tour) {
        // Add the edge to the path
        path.addEdge(edge);

        // Get the next edge in the tour
        E nextEdge = tour.iterator().next();

        // If the next edge is not the same as the current edge, add it to the path
        if (!edge.equals(nextEdge)) {
            path.addEdge(nextEdge);
        }
    }

