private List<Pair<List<Pair<Integer,Integer>>,E>> computeGlobalSeparatorList() {
    // Compute the list of minimal separators for every edge in the graph
    List<Pair<List<Pair<Integer,Integer>>,E>> globalSeparatorList = new ArrayList<>();
    for (E edge : graph.edges()) {
        // Compute the list of minimal separators for the current edge
        List<Pair<Integer,Integer>> minimalSeparators = computeMinimalSeparators(edge);
        globalSeparatorList.add(new Pair<>(minimalSeparators, edge));
    }
    return globalSeparatorList;
}

/**
 * Computes the list of minimal separators for the given edge.
 * @param edge the edge for which the minimal separators are computed
 * @return the list of minimal separators for the given edge
 */
private List<Pair<Integer,Integer>> computeMinimalSeparators(E edge) {
    // Compute the neighborhood of the current edge
    Set<E> neighborhood = graph.neighborhood(edge);

    // Compute the list of minimal separators for the current edge
    List<Pair<Integer,Integer>> minimalSeparators = new ArrayList<>();
    for (E neighbor : neighborhood) {
        // Compute the separator between the current edge and the neighbor
        Pair<Integer,Integer> separator = computeSeparator(edge, neighbor);
        if (separator != null) {
            minimalSeparators.add(separator);
        }
    }
    return minimalSeparators;
}

/**
 * Computes the separator between the given two edges.
 * @param edge1 the first edge
 * @param edge2 the second edge
 * @return the separator between the two edges, or null if there is no separator
 */
private Pair<Integer,Integer> computeSeparator(E edge1, E edge2) {
    // Check if the two edges are adjacent
    if (!graph.areAdjacent(edge1, edge2)) {
        return null;
    }

    // Compute the intersection of the two edges
    Set<Integer> intersection = graph.intersection(edge1, edge2);

    // Check if the intersection is empty
    if (intersection.isEmpty()) {
        return null;
    }

    // Return the first element of the intersection as the separator
    return new Pair<>(intersection.iterator().next(), intersection.size());
}

