List<Integer> computeLowerBounds(List<K> keys) {
    // Initialize the lower bounds to the first key
    List<Integer> lowerBounds = new ArrayList<>(keys.size());
    for (int i = 0; i < keys.size(); i++) {
        lowerBounds.add(keys.get(i));
    }

    // Iterate over the keys in reverse order
    for (int i = keys.size() - 1; i >= 0; i--) {
        // Find the maximum lower bound for the current key
        int maxLowerBound = keys.get(i);
        for (int j = i + 1; j < keys.size(); j++) {
            if (keys.get(j) < maxLowerBound) {
                maxLowerBound = keys.get(j);
            }
        }

        // Update the lower bound for the current key
        lowerBounds.set(i, maxLowerBound);
    }

    return lowerBounds;
}
