public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {

    // Open the file for reading
    try (FileInputStream fis = new FileInputStream(file)) {

        // Create a new BufferedReader for reading the file
        try (BufferedReader br = new BufferedReader(new InputStreamReader(fis))) {

            // Create a new List to store the thread snapshots
            List<ThreadSnapshot> threadSnapshots = new ArrayList<>();

            // Read the file line by line
            String line;
            while ((line = br.readLine()) != null) {

                // Check if the line is a time range
                if (line.startsWith("TimeRange")) {

                    // Parse the time range
                    ProfileAnalyzeTimeRange timeRange = ProfileAnalyzeTimeRange.parseFromString(line);

                    // Check if the time range is in the specified time ranges
                    if (timeRanges.contains(timeRange)) {

                        // Create a new ThreadSnapshot
                        ThreadSnapshot threadSnapshot = new ThreadSnapshot();

                        // Set the time range
                        threadSnapshot.setTimeRange(timeRange);

                        // Read the next line
                        line = br.readLine();

                        // Check if the line is a thread name
                        if (line.startsWith("ThreadName")) {

                            // Parse the thread name
                            String threadName = line.substring(10);

                            // Set the thread name
                            threadSnapshot.setThreadName(threadName);

                            // Read the next line
                            line = br.readLine();

                            // Check if the line is a thread state
                            if (line.startsWith("ThreadState")) {

                                // Parse the thread state
                                String threadState = line.substring(11);

                                // Set the thread state
                                threadSnapshot.setThreadState(threadState);

                                // Read the next line
                                line = br.readLine();

                                // Check if the line is a stack trace
                                if (line.startsWith("StackTrace")) {

                                    // Parse the stack trace
                                    String stackTrace = line.substring(10);

                                    // Set the stack trace
                                    threadSnapshot.setStackTrace(stackTrace);

                                    // Add the thread snapshot to the list
                                    threadSnapshots.add(threadSnapshot);
                                }
                            }
                        }
                    }
                }
            }

            // Return the list of thread snapshots
            return threadSnapshots;
        }
    }
}
